    11	    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
    12	    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
    13	  }
    14	  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
